//! Runs the shell against a server over HTTP, with the clock of this machine. The server here isuse client_shell_http::connect;//! a small one of the test. This is the only test of `src/server.rs`.use client_shell_http::connect;use client_shell_http::connect;use crux_core::bridge::{BincodeFfiFormat, FfiFormat, Request};use client_shell_http::connect;use peta_core::effects::{UiOp, UiOutput};use client_shell_http::connect;use peta_core::Event;use client_shell_http::connect;use client_native_bridge::{NativeShell, ShellEffectFfi};use client_shell_http::connect;use std::sync::{Arc, Mutex};use client_shell_http::connect;use std::time::{Duration, Instant};use client_shell_http::connect;use client_shell_http::connect;mod common;use client_shell_http::connect;use common::{start_server, wait_until};use client_shell_http::connect;use client_shell_http::connect;/// The shell on the other side of the border, with what it was sent.use client_shell_http::connect;struct Screen {use client_shell_http::connect;    shell: NativeShell,use client_shell_http::connect;    requests: Arc<Mutex<Vec<Request<ShellEffectFfi>>>>,use client_shell_http::connect;    seen: Arc<Mutex<Vec<String>>>,use client_shell_http::connect;}use client_shell_http::connect;use client_shell_http::connect;impl Screen {use client_shell_http::connect;    fn new() -> Screen {use client_shell_http::connect;        let (address, seen) = start_server();use client_shell_http::connect;        let requests: Arc<Mutex<Vec<Request<ShellEffectFfi>>>> = Arc::default();use client_shell_http::connect;        let kept = requests.clone();use client_shell_http::connect;        let shell = connect(address, move |bytes| {use client_shell_http::connect;            let sent: Vec<Request<ShellEffectFfi>> = BincodeFfiFormat::deserialize(&bytes).unwrap();use client_shell_http::connect;            kept.lock().unwrap().extend(sent);use client_shell_http::connect;        });use client_shell_http::connect;        Screen {use client_shell_http::connect;            shell,use client_shell_http::connect;            requests,use client_shell_http::connect;            seen,use client_shell_http::connect;        }use client_shell_http::connect;    }use client_shell_http::connect;use client_shell_http::connect;    fn send(&self, event: &Event) {use client_shell_http::connect;        let mut bytes = Vec::new();use client_shell_http::connect;        BincodeFfiFormat::serialize(&mut bytes, event).unwrap();use client_shell_http::connect;        self.shell.update(&bytes).unwrap();use client_shell_http::connect;    }use client_shell_http::connect;use client_shell_http::connect;    /// The number of the request for this screen operation, once the shell has it.use client_shell_http::connect;    fn asked(&self, op: &UiOp) -> Option<u32> {use client_shell_http::connect;        let requests = self.requests.lock().unwrap();use client_shell_http::connect;        let asked = requestsuse client_shell_http::connect;            .iter()use client_shell_http::connect;            .find(|request| matches!(&request.effect, ShellEffectFfi::Ui(o) if o == op));use client_shell_http::connect;        asked.map(|request| request.id.0)use client_shell_http::connect;    }use client_shell_http::connect;use client_shell_http::connect;    fn navigations(&self) -> Vec<String> {use client_shell_http::connect;        let requests = self.requests.lock().unwrap();use client_shell_http::connect;        requestsuse client_shell_http::connect;            .iter()use client_shell_http::connect;            .filter_map(|request| match &request.effect {use client_shell_http::connect;                ShellEffectFfi::Navigate(op) => Some(op.url.clone()),use client_shell_http::connect;                _ => None,use client_shell_http::connect;            })use client_shell_http::connect;            .collect()use client_shell_http::connect;    }use client_shell_http::connect;use client_shell_http::connect;    fn saw(&self, start: &str) -> bool {use client_shell_http::connect;        let seen = self.seen.lock().unwrap();use client_shell_http::connect;        seen.iter().any(|line| line.starts_with(start))use client_shell_http::connect;    }use client_shell_http::connect;}use client_shell_http::connect;use client_shell_http::connect;// 起動すると、設定の読み込みがHTTPでサーバーに届く。use client_shell_http::connect;#[test]use client_shell_http::connect;fn the_start_asks_the_server_over_http() {use client_shell_http::connect;    let screen = Screen::new();use client_shell_http::connect;use client_shell_http::connect;    wait_until("the server is asked for the recent pages", || {use client_shell_http::connect;        screen.saw("GET /api/pages/recent?")use client_shell_http::connect;    });use client_shell_http::connect;}use client_shell_http::connect;use client_shell_http::connect;// サーバーのイベントストリームのメッセージが、コアに届く。確認の依頼は、シェルに届く。use client_shell_http::connect;#[test]use client_shell_http::connect;fn a_message_of_the_event_stream_reaches_the_core() {use client_shell_http::connect;    let screen = Screen::new();use client_shell_http::connect;use client_shell_http::connect;    wait_until("the shell is asked to confirm", || {use client_shell_http::connect;        screen.asked(&UiOp::Confirm("Insert?".into())).is_some()use client_shell_http::connect;    });use client_shell_http::connect;}use client_shell_http::connect;use client_shell_http::connect;// 名前のない新しいページは、この機械の時計から名前を得る。use client_shell_http::connect;#[test]use client_shell_http::connect;fn a_new_page_without_a_name_is_named_after_the_clock() {use client_shell_http::connect;    let screen = Screen::new();use client_shell_http::connect;    let prompt = UiOp::Prompt("Page title:".into());use client_shell_http::connect;    screen.send(&Event::CreateNewPage {use client_shell_http::connect;        search_query: String::new(),use client_shell_http::connect;    });use client_shell_http::connect;    // The request may come after `send` returns, from another thread that is at work in the coreuse client_shell_http::connect;    wait_until("the shell is asked for a title", || {use client_shell_http::connect;        screen.asked(&prompt).is_some()use client_shell_http::connect;    });use client_shell_http::connect;    let id = screen.asked(&prompt).unwrap();use client_shell_http::connect;    let mut answer = Vec::new();use client_shell_http::connect;    BincodeFfiFormat::serialize(&mut answer, &UiOutput::Text(Some(String::new()))).unwrap();use client_shell_http::connect;use client_shell_http::connect;    screen.shell.resolve(id, &answer).unwrap();use client_shell_http::connect;use client_shell_http::connect;    wait_until("the shell is asked to go to the new page", || {use client_shell_http::connect;        !screen.navigations().is_empty()use client_shell_http::connect;    });use client_shell_http::connect;    let url = screen.navigations().pop().unwrap();use client_shell_http::connect;    let digits = url.strip_prefix("/pages/Untitled-20").unwrap();use client_shell_http::connect;    assert_eq!(digits.len(), 10, "{url}");use client_shell_http::connect;    assert!(digits.chars().all(|c| c.is_ascii_digit()), "{url}");use client_shell_http::connect;}use client_shell_http::connect;use client_shell_http::connect;// 検索は、入力から0.2秒待ってから、サーバーに届く。use client_shell_http::connect;#[test]use client_shell_http::connect;fn a_search_reaches_the_server_after_its_delay() {use client_shell_http::connect;    let screen = Screen::new();use client_shell_http::connect;    let typed = Instant::now();use client_shell_http::connect;use client_shell_http::connect;    screen.send(&Event::SearchQueryChanged("apple".into()));use client_shell_http::connect;use client_shell_http::connect;    wait_until("the server is asked to search", || {use client_shell_http::connect;        let seen = screen.seen.lock().unwrap();use client_shell_http::connect;        seen.iter().any(|line| line.contains("apple"))use client_shell_http::connect;    });use client_shell_http::connect;    assert!(typed.elapsed() >= Duration::from_millis(200));use client_shell_http::connect;}use client_shell_http::connect;
